function computeCharWidth(charCode, visibleColumn, tabSize, columnsForFullWidthChar) {
    if (charCode === 9 /* CharCode.Tab */) {
        return (tabSize - (visibleColumn % tabSize));
    }
    if (strings.$fg(charCode)) {
        return columnsForFullWidthChar;
    }
    if (charCode < 32) {
